│   └── main.rs       # Entry point
└── functionfly.jsonc # Function config
```

## Cargo.toml

```toml
[package]
name = "my-function"
version = "0.1.0"
edition = "2021"

[dependencies]
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"

[profile.release]
opt-level = 3
