## Error Handling

```rust
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::io::{self, Read, Write};

#[derive(Deserialize)]
struct Request {
    body: serde_json::Value,
}

#[derive(Serialize)]
struct Response {
    status: u16,
    body: serde_json::Value,
}

fn main() {
    let mut input = String::new();
    if let Err(e) = io::stdin().read_to_string(&mut input) {
        let response = Response {
            status: 400,
            body: json!({"error": format!("Failed to read input: {}", e)}),
        };
        let _ = writeln!(io::stdout(), "{}", serde_json::to_string(&response).unwrap());
        return;
    }

    let request: Request = match serde_json::from_str(&input) {
        Ok(req) => req,
        Err(e) => {
            let response = Response {
                status: 400,
                body: json!({"error": format!("Invalid JSON: {}", e)}),
            };
            let _ = writeln!(io::stdout(), "{}", serde_json::to_string(&response).unwrap());
            return;
        }
    };

    let response = handler(request);
    let output = serde_json::to_string(&response).unwrap();
    io::stdout().write_all(output.as_bytes()).unwrap();
}

fn handler(request: Request) -> Response {
    match process_request(&request.body) {
        Ok(result) => Response {
            status: 200,
            body: result,
        },
        Err(e) => Response {
            status: 500,
            body: json!({"error": e}),
        },
    }
}

fn process_request(body: &serde_json::Value) -> Result<serde_json::Value, String> {
    // Processing logic
    Ok(json!({"status": "ok"}))
}
